refsection.programlisting:
// GF(16) construido con el polinomio primitivo por defecto 1 + x + x^4
F = gf_create_field(2, 4);
gf_primitive_polynomial(F)        // 1 + x + x^4

a = [0 1 0 0];                    // alpha
b = [1 1 0 0];                    // 1 + alpha = alpha^4
c = gf_multiply(F, a, b)          // [0 1 1 0] = alpha + alpha^2
gf_to_exponential(F, c)           // 5: c es alpha^5

// Polinomios sobre GF(2)
[r, q] = gf_poly_divide([1 0 1 1], [1 1], 2)   // r = 1, q = [0 0 1]
